async function editFileFilters(forNew=false){
 if(!forNew&&directFiles()){message('文件直接比较仅包含所选两个文件，无需目录过滤');return;}
 const config=normalizeFileFilters(forNew||!snapshot?newTaskFilters:snapshot.task.fileFilters),dialog=document.createElement('dialog');dialog.id='fileFilterDialog';
 dialog.innerHTML=`<h2>常见无关文件过滤</h2><p>勾选的类型不复制、不比较，也不提供给智能体。保留生成的 C/H、模型、业务 MAT/Bus、工程配置及链接脚本。</p><div class="filter-groups">${FILTER_GROUPS.map(g=>`<label><input type="checkbox" data-file-filter="${g.id}" ${config[g.id]?'checked':''}><span><b>${esc(g.title)}</b><small>${esc(g.detail)}</small></span></label>`).join('')}</div><label>额外排除扩展名（逗号或空格分隔）<input id="extraExtensions" value="${esc(config.extraExtensions.join(', '))}" placeholder="例如 zip, csv"></label><label>额外排除目录（每行一个名称或相对路径）<textarea id="extraFolders" placeholder="例如 backup">${esc(config.extraFolders.join('\n'))}</textarea></label><p class="small">规则随任务保存。关闭过滤时只从原件补齐缺失副本，不覆盖已有编辑；未保存内容不能被排除。计数按文件或整目录入口计算。</p><div class="filter-error error-text"></div><div class="dialog-actions"><button id="resetFileFilters">恢复默认</button><button id="cancelFileFilters">取消</button><button id="applyFileFilters" class="primary">应用</button></div>`;
 document.body.append(dialog);dialog.querySelector('#cancelFileFilters').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();
 dialog.querySelector('#resetFileFilters').onclick=()=>{dialog.querySelectorAll('[data-file-filter]').forEach(b=>b.checked=true);dialog.querySelector('#extraExtensions').value='';dialog.querySelector('#extraFolders').value='';};
 dialog.querySelector('#applyFileFilters').onclick=async()=>{try{const value=normalizeFileFilters({...Object.fromEntries([...dialog.querySelectorAll('[data-file-filter]')].map(b=>[b.dataset.fileFilter,b.checked])),extraExtensions:dialog.querySelector('#extraExtensions').value.split(/[,，;；\s]+/).filter(Boolean),extraFolders:dialog.querySelector('#extraFolders').value.split(/\r?\n/).filter(Boolean)});if(forNew||!snapshot)newTaskFilters=value;else{await flush();setBusy(true,'更新过滤规则，补齐新纳入的工作副本…');const s=await call('fileFilters',{filters:value});snapshot=s;if(rel&&!s.entries.some(n=>n.rel===rel)){rel=null;editor?.setModel(null);switchView('folder');$('#fileTab').disabled=true;}renderTree();renderScope();message('类型过滤已应用；已有工作副本未覆盖');}dialog.close();}catch(e){dialog.querySelector('.filter-error').textContent=e.message;}finally{setBusy(false);}};
 dialog.showModal();
}
function renderScope(){const f=snapshot?.task.filtered,config=snapshot?.task.fileFilters||newTaskFilters,enabled=FILTER_GROUPS.some(g=>config[g.id]!==false)||config.extraExtensions?.length||config.extraFolders?.length;$('#excludedCount').textContent=f?.total?`类型过滤：排除 ${f.total} 个文件/目录入口`:enabled?'类型过滤已启用':'类型过滤已关闭';if(snapshot?.task.scopePaths)$('#excludedCount').textContent+=` · 样本范围 ${snapshot.task.scopePaths.length} 个路径`;$('#excludedCount').title=[...(f?Object.entries(f.reasons).map(([k,v])=>`${k} ${v}`):[]),...(snapshot?.task.scopePaths||[])].join('\n');}
$('#fileScope').onclick=()=>editFileFilters();$('#newFileScope').onclick=()=>editFileFilters(true);

