function setupEditor(){if(editor)return;monaco.editor.defineTheme('archive-light',{base:'vs',inherit:true,rules:[],colors:{'editor.background':'#ffffff','editor.selectionBackground':'#7da9ed99','editor.inactiveSelectionBackground':'#9bbcea99','editor.selectionHighlightBackground':'#b5cff060','editor.selectionForeground':'#102b4e','diffEditor.insertedTextBackground':'#98dcb050','diffEditor.removedTextBackground':'#f3a4a650','diffEditor.insertedLineBackground':'#effaf1','diffEditor.removedLineBackground':'#fff1f1','editorGutter.background':'#f8f9fb'}});editor=monaco.editor.createDiffEditor($('#editor'),{theme:'archive-light',automaticLayout:true,roundedSelection:false,originalEditable:true,readOnly:false,renderSideBySide:true,useInlineViewWhenSpaceIsLimited:false,ignoreTrimWhitespace:false,renderIndicators:true,enableSplitViewResizing:true,renderMarginRevertIcon:false,renderOverviewRuler:true,minimap:{enabled:false},fontSize:14,fontFamily:"Consolas, 'Microsoft YaHei', monospace",lineHeight:23,scrollBeyondLastLine:false,wordWrap:'off',diffWordWrap:'off',hideUnchangedRegions:{enabled:false},maxComputationTime:5000});
  mergeGutter=createMergeGutter($('#editor'),editor,protect(async(index,direction)=>{changeIndex=index;selectedRow=0;await merge(direction);}));
  editor.updateOptions({editContext:false,contextmenu:false});
  for(const side of ['ref','test']){const ed=side==='ref'?editor.getOriginalEditor():editor.getModifiedEditor();ed.onDidFocusEditorText(()=>{activeSide=side;renderSelection();});ed.onDidChangeCursorSelection(()=>{updateContext();renderSelection();});ed.onDidChangeModelContent(()=>{if(syncing||!rel)return;const b=buffers.get(side+':'+rel);if(!b)return;b.localText=ed.getValue();b.localDirty=b.localText!==b.baseText;clearTimeout(dirtyTimer);dirtyTimer=setTimeout(()=>protect(flush)(),250);renderMeta();});ed.onContextMenu(e=>{activeSide=side;e.event.preventDefault();e.event.stopPropagation();showMenu(e.event.posx,e.event.posy,fileMenu());});}
  for(const ed of [editor.getOriginalEditor(),editor.getModifiedEditor()])ed.onDidChangeModelContent(()=>{if(!syncing)recomputeBlocks();});
  editor.onDidUpdateDiff(()=>{if(!syncing)recomputeBlocks();});
}
function recomputeBlocks(){if(!editor?.getModel())return;try{changes=differenceBlocks(editor.getOriginalEditor().getValue(),editor.getModifiedEditor().getValue());changeIndex=Math.min(changeIndex,Math.max(0,changes.length-1));$('#diffCount').textContent=changes.length?`${changeIndex+1} / ${changes.length}`:'无文本差异';renderBlocks();}catch(e){changes=[];$('#diffCount').textContent='比较未完成';message(e.message,true);}for(const id of ['mergeLeft','mergeRight','lineLeft','lineRight'])$('#'+id).disabled=!changes.length;}
function renderBlocks(){if(!editor?.getModel())return;$('#prevDiff').disabled=$('#nextDiff').disabled=!changes.length;mergeGutter?.render(changes,changeIndex);$('#blockTotal').textContent=changes.length;$('#blockList').innerHTML=changes.map((h,i)=>`<div class="block-card ${i===changeIndex?'current':''}"><button class="block-select" data-block="${i}">差异块 ${i+1}<small>ref ${h.a0+1}–${h.a1} ↔ test ${h.b0+1}–${h.b1}</small></button><div><button data-copy-block="${i}" data-dir="left" title="仅此块复制到 ref">←</button><button data-copy-block="${i}" data-dir="right" title="仅此块复制到 test">→</button></div></div>`).join('')||'<p class="small">无文本差异</p>';const h=changes[changeIndex];const rows=h?blockRows(editor.getOriginalEditor().getValue(),editor.getModifiedEditor().getValue(),h):[];selectedRow=Math.min(selectedRow,Math.max(0,rows.length-1));$('#lineList').innerHTML=rows.map((r,i)=>`<div class="line-pair ${i===selectedRow?'current':''}" data-line-row="${i}" title="${esc('ref: '+(r.left??'缺失')+'\ntest: '+(r.right??'缺失'))}"><button data-select-row="${i}"><span>L${r.a===null?'—':r.a+1} ${esc(r.left??'〈空位〉')}</span><span>R${r.b===null?'—':r.b+1} ${esc(r.right??'〈空位〉')}</span></button><div><button data-copy-row="${i}" data-dir="left">←</button><button data-copy-row="${i}" data-dir="right">→</button></div></div>`).join('');$('#lineScope').textContent=rows.length?`当前块第 ${selectedRow+1} 个对应行；缺失侧复制表示删除目标行`:'无差异行';}
function selectBlock(i){changeIndex=i;selectedRow=0;const c=changes[i];if(!c)return;editor.getOriginalEditor().revealLineInCenter(Math.max(1,c.a0+1));editor.getModifiedEditor().revealLineInCenter(Math.max(1,c.b0+1));$('#diffCount').textContent=`${i+1} / ${changes.length}`;renderBlocks();}
function beginMerge(){if(mergePending)throw Error('正在同步上一处复制，请稍后操作');if(!rel||view!=='text'||!editor?.getModel())throw Error('请先打开文本比较');mergePending=true;return {rel,taskId:snapshot.task.id,index:changeIndex,left:editor.getOriginalEditor().getValue(),right:editor.getModifiedEditor().getValue()};}
function verifyMerge(op){if(rel!==op.rel||snapshot.task.id!==op.taskId||view!=='text'||editor.getOriginalEditor().getValue()!==op.left||editor.getModifiedEditor().getValue()!==op.right)throw Error('复制前比较内容已变化，请重新选择差异');changeIndex=op.index;}
async function mergeRow(direction,row=selectedRow){const op=beginMerge();try{await flush();verifyMerge(op);recomputeBlocks();const h=changes[op.index];if(!h)return;const target=direction==='right'?editor.getModifiedEditor():editor.getOriginalEditor(),text=copyRow(op.left,op.right,h,row,direction);activeSide=direction==='right'?'test':'ref';target.pushUndoStop();target.executeEdits('copy-aligned-line',[{range:target.getModel().getFullModelRange(),text,forceMoveMarkers:true}]);target.pushUndoStop();await flush();recomputeBlocks();message(`仅对应单行已复制到 ${activeSide} 缓冲区，差异块已更新，可撤销`);}finally{mergePending=false;}}
async function flush(){clearTimeout(dirtyTimer);const r=rel;if(!editor?.getModel()||!r||view!=='text')return;const edits=['ref','test'].map(side=>({side,rel:r,text:(side==='ref'?editor.getOriginalEditor():editor.getModifiedEditor()).getValue()}));updateChain=updateChain.then(async()=>{for(const a of edits){const key=a.side+':'+a.rel,b=buffers.get(key);if(b&&a.text!==b.text){const result=await call('update',{...a,revision:b.revision});buffers.set(key,{...result,localText:a.text});}}renderMeta();});try{await updateChain;}catch(e){updateChain=Promise.resolve();throw e;}}
function language(r){return /\.m$/i.test(r)?'matlab':/\.(c|h|cpp|hpp|cc)$/i.test(r)?'cpp':/\.py$/i.test(r)?'python':/\.(js|mjs|json)$/i.test(r)?'javascript':'plaintext';}
function switchView(which){view=which;document.body.dataset.view=which;$('#welcome').hidden=!!snapshot;$('#comparison').hidden=!snapshot;$('#folderView').hidden=which!=='folder';$('#textView').hidden=which!=='text';$('#modelView').hidden=which!=='model';$('#csplusView').hidden=which!=='csplus';csplusView.setActive(which==='csplus');$('#folderTab').classList.toggle('active',which==='folder');$('#fileTab').classList.toggle('active',which==='text'||which==='model');if(which==='text'){setupEditor();requestAnimationFrame(()=>editor.layout());}updateContext();}
