function selection(){if(!rel||view!=='text'||!editor)return null;const ed=activeSide==='ref'?editor.getOriginalEditor():editor.getModifiedEditor(),sel=ed.getSelection();if(sel&&!sel.isEmpty())return {side:activeSide,path:rel,start:sel.startLineNumber,end:sel.endLineNumber,text:ed.getModel().getValueInRange(sel),revision:buffers.get(activeSide+':'+rel)?.revision};const c=changes[changeIndex];return {side:activeSide,path:rel,hunk:c||null,revision:buffers.get(activeSide+':'+rel)?.revision};}
