  if(view==='csplus'){const c=csplusView.context();return c?{...c,rel:null,label:`CS+${c.module?' / '+c.module:''} · ref: ${c.files.ref||'未配置'} ↔ test: ${c.files.test||'未配置'}`}:{rel:null,label:'CS+：请先选择配置文件'};}
