async function authorizedRead(side,r){if(directMode())throw Error('原文件模式不提供 MATLAB 副本导入，请勾选创建副本');const dialog=document.createElement('dialog');dialog.innerHTML=`<h2>MATLAB 授权原生读取</h2><p>${esc(side+'/'+r)} · 原件只读，缓存进入任务目录。</p><label>MATLAB R2024b matlab.exe<input class="exe" placeholder="留空自动查找"></label><label><input class="grant" type="checkbox" style="width:auto"> 公司 IT 已授权 MATLAB 读取此文件</label><div class="dialog-actions"><button class="cancel">取消</button><button class="continue primary">授权读取</button></div>`;document.body.append(dialog);const choice=new Promise(resolve=>{dialog.onclose=()=>resolve(dialog.returnValue);});dialog.querySelector('.cancel').onclick=()=>dialog.close('cancel');dialog.querySelector('.continue').onclick=()=>{if(dialog.querySelector('.grant').checked)dialog.close('ok');};dialog.showModal();const result=await choice,exe=dialog.querySelector('.exe').value.trim();dialog.remove();if(result!=='ok')return;setBusy(true,'MATLAB 授权原生读取…');try{const result=await call('matlabRead',{side,rel:r,exe:exe||undefined,authorized:true});await rescan(false);message(result.status);}finally{setBusy(false);}}
