  const r=await call('agentAsk',{question,selection:context.selection,rel:context.rel,files:context.files,moduleId:context.moduleId,write,effort:$('#aiEffort').value,maxCalls:Number($('#maxCalls').value),maxChars:Number($('#maxChars').value),timeout:Number($('#timeout').value)});
  answerText=r.text||r.error||aiStateName(r.status);flushAnswer();$('#aiStatus').textContent='已连接 · 当前任务会话';$('#connectAI').textContent='连接状态';
  $('#aiActivity').textContent=`${aiStateName(r.status)} · 总计 ${(r.metrics.totalMs/1000).toFixed(1)}s · 首字 ${r.metrics.firstTextMs==null?'—':(r.metrics.firstTextMs/1000).toFixed(1)+'s'}`;message(`Codex ${aiStateName(r.status)} · 工具 ${r.budget.calls} 次 · 读取 ${r.budget.chars} 字符`);snapshot.task.chat=r.chat;
