function modelProperty(c){const key=c.property||c.kind,names={unmatched:'单侧节点',structure:'结构变化',ElementOrder:'Bus 元素顺序',ElementPresence:'Bus 元素增删',FieldOrder:'结构体字段顺序',FieldPresence:'字段增删',VariablePresence:'变量存在性',DataType:'数据类型',Dimensions:'维度',Value:'值'};return names[key]?names[key]+' · '+key:key;}
