api.onEvent(({type,payload})=>{if(type==='ai-phase'){aiPhase=payload.stage+(payload.detail?' · '+payload.detail:'');aiLast=Date.now();renderAiActivity();$('#tools').textContent+=`[${(payload.elapsedMs/1000).toFixed(1)}s] ${aiPhase}\n`;}if(type==='ai-delta'||type==='tool')aiLast=Date.now();if(type==='ai-summary'){$('#tools').textContent+=payload;}if(type==='matlab-state'){matlabActive=payload.active!==false;renderProgress();if(payload.total){$('#progress').value=payload.current;$('#progress').max=payload.total;}message(payload.stage+(payload.total?` · ${payload.current}/${payload.total}`:''));}if(type==='matlab-finished'){matlabActive=false;renderProgress();}if(type==='matlab-results'){snapshot=payload;renderTree();renderScope();if(view==='model'&&rel)showModelResult(rel);}if(type==='matlab-batch-error'){matlabActive=false;renderProgress();message('MATLAB 自动比较失败：'+payload.message,true);}});
